const P:usize=8;const T:usize=12;
#[no_mangle] pub unsafe extern "C" fn bitmask_assignment_count(input:*const i64,len:usize)->i64{if input.is_null()||len<2||len>106{return -1}let a=std::slice::from_raw_parts(input,len);if a[0]<0||a[0]>P as i64||a[1]<0||a[1]>T as i64{return -1}let people=a[0] as usize;let tasks=a[1] as usize;let mut freq=[[0i64;P];T+1];let mut pos=2;for p in 0..people{if pos>=len{return -1}let c=a[pos];pos+=1;if c<0||c>T as i64||pos+c as usize>len{return -1}for _ in 0..c{let task=a[pos];pos+=1;if task<1||task>tasks as i64{return -1}freq[task as usize][p]+=1}}if pos!=len{return -1}let states=1usize<<people;let full=states-1;let mut dp=[[0i64;T+2];1<<P];for mask in 0..states{dp[mask][tasks+1]=if mask==full{1}else{0}}for task in (1..=tasks).rev(){for mask in 0..states{let mut ways=dp[mask][task+1];for p in 0..people{if freq[task][p]>0&&(mask&(1<<p))==0{ways+=freq[task][p]*dp[mask|(1<<p)][task+1]}}dp[mask][task]=ways}}dp[0][1]}
